import{_ as a,o as t,c as r,a2 as p}from"./chunks/framework.DfDAiEgj.js";const _=JSON.parse('{"title":"盒马鲜生","description":"","frontmatter":{},"headers":[],"relativePath":"experience/hema.md","filePath":"experience/hema.md","lastUpdated":null}'),l={name:"experience/hema.md"};function o(i,e,n,h,s,c){return t(),r("div",null,[...e[0]||(e[0]=[p('<h1 id="盒马鲜生" tabindex="-1">盒马鲜生 <a class="header-anchor" href="#盒马鲜生" aria-label="Permalink to &quot;盒马鲜生&quot;">​</a></h1><h2 id="观察" tabindex="-1">观察 <a class="header-anchor" href="#观察" aria-label="Permalink to &quot;观察&quot;">​</a></h2><p>“观察”的方式：</p><p>保持空无，抛下预设 ↓ 用客体视角觉察出自己内心与行为的关系 ↓ 再试着深入“阅读”他人内心与行为的关系 ↓ 结合规律，分析出外界真实的需要 ↓ 在生活与工作中做出策略调整或反应 ↓ 保持练习，达到情商和洞察力的提高</p><h2 id="练习-关联性-思维的方式" tabindex="-1">练习“关联性”思维的方式： <a class="header-anchor" href="#练习-关联性-思维的方式" aria-label="Permalink to &quot;练习“关联性”思维的方式：&quot;">​</a></h2><p>抛开过去那种任何事都想着“自己干”的想法，问自己3个问题:</p><ol><li>我现在要做的事情，有没有利他性？</li><li>可以不可以与他人形成合力？</li><li>最终取得的成果，能不能多方共享？</li></ol><hr><p>如果3个问题想清楚了没问题，那么不怕拒绝，厚着脸皮干就完了！</p><p>日常要留心，自己和他人身上，有哪些可以“做成事”的资源，这并不是要人学会自利，而是需要培养自己的协作性。自己的专业知识，钱，甚至体力，时间，人脉圈，都是能一起互相协作的资源。</p><p>除了人与人的资源关联性，还可以培养物与物相互跨界联系的能力。</p><p>比如在阿里，训练公关的新闻策划能力，就有一种称之为“两只试管法”的日常思考方法，你可以想象成左手握一个产品试管，右手握一个情绪试管，然后两种试剂倒在了一起，产生神奇的化学反应。</p><p>比如：</p><p>盒马鲜生（线下的果蔬生鲜服务设施/一种都市快节奏生活方式）+ 房价（情绪饱满的高敏感民生话题）= 品牌概念：盒区房</p><p>进口水果 + 北上广的生活压力（情绪饱满的消费焦虑）= 热门话题：车厘子自由</p><p>疫情期间，盒马线上订单量同比激增220%，一度面临人手不够的情况，与其他餐饮品牌联手“共享”员工以满足用户爆发的需求，而生鲜电商能在近期得到诸多青睐的一大原因在于，在生鲜电商发展的八年间，消费者已经通过综合电商和外卖平台培养出了线上购物的心智。 <a href="https://www.chinaz.com/2020/0312/1116987.shtml" target="_blank" rel="noreferrer">2</a></p>',16)])])}const m=a(l,[["render",o]]);export{_ as __pageData,m as default};
